["UID"] = "0x68afcab719b8b",
["Hooks"] = {
["Nameplate Updated"] = "------------------------------------------------------------\n-- NAMEPLATE UPDATED\n------------------------------------------------------------\nfunction (self, unitId, unitFrame, envTable, modTable)\n    \n    local cfg       = modTable.config or {}\n    local container = envTable.questContainer\n    local icon      = envTable.questIcon\n    local text      = envTable.questText\n    local badge     = envTable.groupBadge\n    if not icon or not text then return end\n    \n    if container and modTable.AME_QuestApplyContainerZ then\n        modTable.AME_QuestApplyContainerZ(container, unitFrame, unitFrame.healthBar, cfg.iconstrata)\n    end\n    \n    ------------------------------------------------------------\n    -- ICON + TEXT HELPERS\n    ------------------------------------------------------------\n    local function setIconTexture(tex, atlas, fallback)\n        if tex.SetAtlas and atlas then\n            if tex:SetAtlas(atlas) then return end\n        end\n        if fallback then tex:SetTexture(fallback) end\n    end\n    \n    local function setIcon(which)\n        if which == \"bag\" then\n            setIconTexture(icon, modTable.ATLAS_BAG, modTable.TEX_BAG)\n            icon:SetSize(cfg.iconBagSize or 34, cfg.iconBagSize or 34)\n        else\n            setIconTexture(icon, modTable.ATLAS_SKULL, modTable.TEX_SKULL)\n            icon:SetSize(cfg.iconSkullSize or 26, cfg.iconSkullSize or 26)\n        end\n    end\n    \n    local function anchor(which)\n        local map  = envTable.anchorMap or {}\n        local side = tonumber(cfg.iconAnchorSide) or 7\n        local a    = map[side] or {\"BOTTOMLEFT\", \"BOTTOMLEFT\"}\n        \n        local x = (which == \"bag\") and (cfg.bagNudgeX or 0) or (cfg.skullNudgeX or 0)\n        local y = (which == \"bag\") and (cfg.iconAnchorYBag or 0) or (cfg.iconAnchorYSkull or 0)\n        \n        icon:ClearAllPoints()\n        icon:SetPoint(a[1], unitFrame.healthBar, a[2], x, y)\n    end\n    \n    ------------------------------------------------------------\n    -- TEXT STYLE (inkl. FontFace: LSM-Name ODER direkter Pfad)\n    ------------------------------------------------------------\n    local function applyTextStyle()\n        modTable.__ameFontCache = modTable.__ameFontCache or {}\n        local cache = modTable.__ameFontCache\n        \n        local face = cfg.textFontFace\n        if type(face) == \"string\" then\n            face = face:match(\"^%s*(.-)%s*$\")\n            if face == \"\" then face = nil end\n        else\n            face = nil\n        end\n        \n        local size  = tonumber(cfg.textSize) or text.__ameDefaultSize or 12\n        local flags = cfg.textOutline or text.__ameDefaultFlags or \"OUTLINE\"\n        if flags == \"NONE\" then flags = \"\" end\n        \n        local cacheKey = face or \"__DEFAULT__\"\n        local fontPath = cache[cacheKey]\n        \n        if fontPath == nil then\n            local resolved\n            \n            -- 1) LSM Name -> Pfad\n            local LSM = LibStub and LibStub(\"LibSharedMedia-3.0\", true)\n            if face and LSM and LSM.HashTable then\n                local ht = LSM:HashTable(\"font\")\n                if ht then\n                    resolved = ht[face]\n                    if not resolved then\n                        local want = face:lower()\n                        for k, v in pairs(ht) do\n                            if type(k) == \"string\" and k:lower() == want then\n                                resolved = v\n                                break\n                            end\n                        end\n                    end\n                end\n            end\n            \n            -- 2) Direkter Pfad erlaubt\n            if face and not resolved then\n                local low = face:lower()\n                if face:find(\"\\\\\") or face:find(\"/\") or low:match(\"%.ttf$\") or low:match(\"%.otf$\") then\n                    resolved = face\n                end\n            end\n            \n            -- 3) Default fallback\n            if not resolved then\n                resolved = text.__ameDefaultFont or (text.GetFont and text:GetFont()) or \"Fonts\\\\FRIZQT__.TTF\"\n            end\n            \n            cache[cacheKey] = resolved\n            fontPath = resolved\n        end\n        \n        local ok = false\n        if type(fontPath) == \"string\" and fontPath ~= \"\" then\n            ok = (text:SetFont(fontPath, size, flags) == true)\n        end\n        \n        if not ok then\n            local fallback = text.__ameDefaultFont or (text.GetFont and text:GetFont()) or \"Fonts\\\\FRIZQT__.TTF\"\n            text:SetFont(fallback, (text.__ameDefaultSize or 12), (text.__ameDefaultFlags or \"\"))\n        end\n        \n        local c = cfg.textColor or {1,1,1,1}\n        Plater:SetFontColor(text, c[1], c[2], c[3], c[4] or 1)\n        \n        text:SetShadowColor(0,0,0, cfg.textShadowAlpha or 0)\n        text:SetShadowOffset(cfg.textShadowX or 0, cfg.textShadowY or -1)\n        \n        text:ClearAllPoints()\n        text:SetPoint(\"CENTER\", icon, \"CENTER\", cfg.textXOffset or 10, cfg.textYOffset or -6)\n    end\n    \n    \n    ------------------------------------------------------------\n    -- TEST MODE (OVERRIDES EVERYTHING)\n    ------------------------------------------------------------\n    if cfg.testMode then\n        local value = tostring(cfg.testValue or 3)\n        \n        -- Reset\n        icon:Hide()\n        text:Hide()\n        if badge then badge:Hide() end\n        \n        -- Wenn Testmode an ist, aber kein Toggle gewählt -> NICHTS anzeigen\n        local any = cfg.testUseSkull or cfg.testUseBag or cfg.testUseGroup\n        if not any then\n            icon:Hide()\n            text:Hide()\n            if badge then badge:Hide() end\n            return\n        end\n        \n        if cfg.testUseSkull then\n            setIcon(\"skull\")\n            anchor(\"skull\")\n            applyTextStyle()\n            text:SetText(value)\n            icon:Show()\n            text:Show()\n            return\n        end\n        \n        if cfg.testUseBag then\n            setIcon(\"bag\")\n            anchor(\"bag\")\n            applyTextStyle()\n            text:SetText(value)\n            icon:Show()\n            text:Show()\n            return\n        end\n        \n        if cfg.testUseGroup and badge then\n            badge:SetSize(cfg.groupBadgeSize or 18, cfg.groupBadgeSize or 18)\n            \n            local map  = envTable.anchorMap or {}\n            local side = tonumber(cfg.groupAnchorSide) or 5\n            local a    = map[side] or {\"CENTER\", \"CENTER\"}\n            \n            badge:ClearAllPoints()\n            badge:SetPoint(a[1], unitFrame.healthBar, a[2],\n                cfg.groupBadgeOffsetX or 0,\n                cfg.groupBadgeOffsetY or 0\n            )\n            \n            local c = cfg.groupColor or {1,1,1,1}\n            badge:SetVertexColor(c[1], c[2], c[3], c[4] or 1)\n            badge:Show()\n            return\n        end\n        \n        return\n    end\n    \n    ------------------------------------------------------------\n    -- ONLY REAL QUEST OBJECTIVES (normal mode)\n    ------------------------------------------------------------\n    if not unitFrame.namePlateIsQuestObjective then\n        icon:Hide()\n        text:SetText(\"\")\n        text:Hide()\n        if badge then badge:Hide() end\n        return\n    end\n    \n    ------------------------------------------------------------\n    -- MULTI LANGUAGE WORD LIST\n    ------------------------------------------------------------\n    local WORDS = {\n        deDE = {\n            KILL = [[getötet, toten, tötet, töten, erschlagen, erlegt, ausgelöscht, zerstört, vernichtet, beschützt, verteidigt, herausgefordert, gegen, zerquetscht, zurückerobert, besiegen, besiegt, ausmerzen, jagt, Kopf, konfrontiert, bekämpft, Überzeugt, bezwungen]],\n            LOOT = [[sammeln, gesammelt, einsammeln, bringt, liefert, besorge]]\n        },\n        enUS = {\n            KILL = [[kill, killed, slay, slain, defeat, defeated, destroy, destroyed, eliminate, eliminated, protect, defend, challenged, against, crush, reclaim, confronted, Convince, slaughtered, fight]],\n            LOOT = [[collect, collected, gather, gathered, bring, brought, recover, recovered]]\n        },\n        frFR = {\n            KILL = [[tuer, tué, abattre, abattu, vaincre, vaincu, détruire, détruit, éliminer, éliminé, protéger, défendre, affronter, contre, écraser, reconquérir, confronté, Convaincre, massacrés, Combattre, affrontée]],\n            LOOT = [[collecter, collecté, ramasser, ramassé, apporter, livrer, récupérer]]\n        },\n        esES = {\n            KILL = [[matar, muerto, derrotar, derrotado, destruir, destruido, eliminar, eliminado, proteger, defender, enfrentar, contra, aplastar, recuperar territorio, confrontada, Convence, asesinados, Lucha]],\n            LOOT = [[recolectar, recolectado, recoger, recogido, traer, entregar, recuperar]]\n        },\n        itIT = {\n            KILL = [[uccidere, ucciso, sconfiggere, sconfitto, distruggere, distrutto, eliminare, eliminato, proteggere, difendere, affrontare, contro, schiacciare, riconquistare, confrontato, Convinci, Uccidi, Combatti, Affronta]],\n            LOOT = [[raccogliere, raccolto, recuperare, recuperato, portare, consegnare]]\n        }\n    }\n    \n    WORDS.enGB = WORDS.enUS\n    local L = WORDS[GetLocale()] or WORDS.enUS\n    \n    local function containsAny(txt, list)\n        if not txt or not list then return false end\n        txt = txt:lower()\n        for phrase in list:gmatch(\"[^,]+\") do\n            phrase = phrase:match(\"^%s*(.-)%s*$\")\n            if phrase ~= \"\" and txt:find(phrase, 1, true) then\n                return true\n            end\n        end\n        return false\n    end\n    \n    ------------------------------------------------------------\n    -- QUEST LOGIC\n    ------------------------------------------------------------\n    local found, display, which = false, \"\", \"skull\"\n    local showGroup = false\n    local groupOnly = false\n    \n    local inGroup = (IsInGroup() or IsInRaid())\n    \n    if unitFrame.QuestInfo then\n        for _, qi in ipairs(unitFrame.QuestInfo) do\n            \n            -- (Optional) Wenn Plater doch Group-Infos reinpackt:\n            if inGroup and qi and qi.yourQuest == false and qi.finished == false then\n                showGroup = true\n                groupOnly = true\n            end\n            \n            if qi and qi.yourQuest and not qi.finished then\n                local qtext = (qi.questText or \"\"):lower()\n                \n                -- Prozent-Quest\n                if not qi.total then\n                    local curr = qi.amount or 0\n                    display = cfg.percentRemaining and (100 - curr) .. \"%\" or curr .. \"%\"\n                    which = \"skull\"\n                    found = true\n                    break\n                end\n                \n                -- Normale Quest\n                local remain = qi.total - (qi.amount or 0)\n                if remain > 0 then\n                    display = tostring(remain)\n                    \n                    -- NUR Kill entscheidet\n                    if containsAny(qtext, L.KILL) then\n                        which = \"skull\"\n                    else\n                        which = \"bag\"\n                    end\n                    \n                    found = true\n                    break\n                end\n            end\n        end\n    end\n    \n    -- Quest Fallback:\n    -- Wenn du in Gruppe bist und das Nameplate ein Questziel ist,\n    -- aber DU selbst nichts mehr brauchst, dann ist es sehr wahrscheinlich ein Group-Objective.\n    if inGroup and cfg.showGroupBadge and unitFrame.namePlateIsQuestObjective and not found then\n        showGroup = true\n        groupOnly = true\n    end\n    \n    ------------------------------------------------------------\n    -- APPLY\n    ------------------------------------------------------------\n    if found then\n        setIcon(which)\n        anchor(which)\n        applyTextStyle()\n        text:SetText(display)\n        text:Show()\n        icon:Show()\n        \n    elseif groupOnly and badge and cfg.showGroupBadge then\n        icon:Hide()\n        text:SetText(\"\")\n        text:Hide()\n    else\n        icon:Hide()\n        text:SetText(\"\")\n        text:Hide()\n    end\n    \n    ------------------------------------------------------------\n    -- GROUP BADGE\n    ------------------------------------------------------------\n    if badge then\n        local shouldShow = cfg.showGroupBadge and showGroup and (found or groupOnly)\n        \n        if shouldShow then\n            badge:SetSize(cfg.groupBadgeSize or 18, cfg.groupBadgeSize or 18)\n            \n            local map  = envTable.anchorMap or {}\n            local side = tonumber(cfg.groupAnchorSide) or 5\n            local a    = map[side] or {\"CENTER\", \"CENTER\"}\n            \n            badge:ClearAllPoints()\n            \n            local anchorTo = found and icon or unitFrame.healthBar\n            \n            badge:SetPoint(a[1], anchorTo, a[2],\n                cfg.groupBadgeOffsetX or 0,\n                cfg.groupBadgeOffsetY or 0\n            )\n            \n            local c = cfg.groupColor or {1,1,1,1}\n            badge:SetVertexColor(c[1], c[2], c[3], c[4] or 1)\n            \n            badge:Show()\n        else\n            badge:Hide()\n        end\n    end\nend",
["Initialization"] = "------------------------------------------------------------\n-- INITIALIZATION\n------------------------------------------------------------\nfunction (modTable)\n    \n    modTable.config = modTable.config or {}\n    local cfg = modTable.config\n    local function d(k, v) if cfg[k] == nil then cfg[k] = v end end\n    \n    ------------------------------------------------------------\n    -- Test Mode (3 Toggles: Skull / Bag / Group)\n    ------------------------------------------------------------\n    d(\"testMode\", false)\n    \n    d(\"testUseSkull\", false)\n    d(\"testUseBag\", false)\n    d(\"testUseGroup\", false)\n    \n    d(\"testValue\", 3)\n    \n    ------------------------------------------------------------\n    -- Position / Anchor\n    ------------------------------------------------------------\n    d(\"iconAnchorSide\", 7)\n    \n    -- Separate X Offsets\n    d(\"skullNudgeX\", 0)\n    d(\"bagNudgeX\", 0)\n    \n    -- Separate Y Offsets\n    d(\"iconAnchorYSkull\", 0)\n    d(\"iconAnchorYBag\", 0)\n    \n    ------------------------------------------------------------\n    -- Icon Appearance\n    ------------------------------------------------------------\n    d(\"iconSkullSize\", 26)\n    d(\"iconBagSize\", 34)\n    d(\"iconstrata\", false)\n    \n    ------------------------------------------------------------\n    -- Text & Display\n    ------------------------------------------------------------\n    d(\"textSize\", 12)\n    d(\"textColor\", {1,1,1,1})\n    d(\"textOutline\", \"OUTLINE\")\n    d(\"textFontFace\", nil)\n    d(\"textXOffset\", 10)\n    d(\"textYOffset\", -6)\n    \n    ------------------------------------------------------------\n    -- Shadow\n    ------------------------------------------------------------\n    d(\"textShadowAlpha\", 0.75)\n    d(\"textShadowX\", 0)\n    d(\"textShadowY\", -1)\n    \n    ------------------------------------------------------------\n    -- Extras\n    ------------------------------------------------------------\n    d(\"percentRemaining\", false)\n    \n    ------------------------------------------------------------\n    -- Group Badge (REAL + TEST)\n    ------------------------------------------------------------\n    d(\"showGroupBadge\", true)\n    d(\"groupBadgeSize\", 18)\n    d(\"groupBadgeOffsetX\", 0)\n    d(\"groupBadgeOffsetY\", 0)\n    d(\"groupColor\", {1,1,1,1})\n    d(\"groupAnchorSide\", 5)\n    \n    ------------------------------------------------------------\n    -- Icons (Atlas + Fallback)\n    ------------------------------------------------------------\n    modTable.ATLAS_SKULL = \"GM-icon-difficulty-normal-hover\"\n    modTable.ATLAS_BAG   = \"Banker\"\n    modTable.ATLAS_GROUP = \"GM-icon-assist-hover\"\n    \n    modTable.TEX_SKULL = [[Interface\\TargetingFrame\\UI-RaidTargetingIcon_8]]\n    modTable.TEX_BAG   = [[Interface\\GroupFrame\\UI-Group-MasterLooter]]\n    \n    ------------------------------------------------------------\n    -- STRATA / FRAMELEVEL\n    ------------------------------------------------------------\n    local STRATA_ORDER = {\n        BACKGROUND = 1, LOW = 2, MEDIUM = 3, HIGH = 4,\n        DIALOG = 5, FULLSCREEN = 6, FULLSCREEN_DIALOG = 7, TOOLTIP = 8,\n    }\n    \n    local function maxStrata(a, b)\n        a = a or \"MEDIUM\"\n        b = b or \"MEDIUM\"\n        local oa = STRATA_ORDER[a] or 3\n        local ob = STRATA_ORDER[b] or 3\n        return (ob > oa) and b or a\n    end\n    \n    function modTable.AME_QuestApplyContainerZ(container, unitFrame, hb, enabled)\n        if not container or not unitFrame then return end\n        \n        if enabled then\n            local parent = hb or unitFrame\n            container:SetParent(parent)\n            \n            local s = maxStrata(\n                parent and parent.GetFrameStrata and parent:GetFrameStrata(),\n                unitFrame:GetFrameStrata()\n            )\n            container:SetFrameStrata(s or \"MEDIUM\")\n            \n            local base = 1\n            if unitFrame.GetFrameLevel then\n                base = math.max(base, unitFrame:GetFrameLevel() or 1)\n            end\n            if hb and hb.GetFrameLevel then\n                base = math.max(base, hb:GetFrameLevel() or 1)\n            end\n            \n            container:SetFrameLevel(base + 120)\n        else\n            container:SetParent(unitFrame)\n            container:SetFrameStrata(unitFrame:GetFrameStrata() or \"MEDIUM\")\n            container:SetFrameLevel((unitFrame:GetFrameLevel() or 1) + 15)\n        end\n    end\n    \nend\n\n\n",
["Constructor"] = "------------------------------------------------------------\n-- CONSTRUCTOR\n------------------------------------------------------------\nfunction (self, unitId, unitFrame, envTable, modTable)\n    \n    local cfg = modTable.config or {}\n    \n    envTable.anchorMap = envTable.anchorMap or {\n        [1] = {\"TOPLEFT\", \"TOPLEFT\"},   [2] = {\"TOP\", \"TOP\"},       [3] = {\"TOPRIGHT\", \"TOPRIGHT\"},\n        [4] = {\"LEFT\", \"LEFT\"},         [5] = {\"CENTER\", \"CENTER\"}, [6] = {\"RIGHT\", \"RIGHT\"},\n        [7] = {\"BOTTOMLEFT\", \"BOTTOMLEFT\"}, [8] = {\"BOTTOM\", \"BOTTOM\"}, [9] = {\"BOTTOMRIGHT\", \"BOTTOMRIGHT\"},\n    }\n    \n    if not envTable.questContainer then\n        local container = CreateFrame(\"Frame\", nil, unitFrame)\n        container:SetFrameStrata(unitFrame:GetFrameStrata() or \"MEDIUM\")\n        container:SetFrameLevel((unitFrame:GetFrameLevel() or 1) + 15)\n        envTable.questContainer = container\n    end\n    \n    local container = envTable.questContainer\n    \n    if modTable.AME_QuestApplyContainerZ then\n        modTable.AME_QuestApplyContainerZ(container, unitFrame, unitFrame.healthBar, cfg.iconstrata)\n    end\n    \n    if not envTable.questIcon then\n        local icon = container:CreateTexture(nil, \"OVERLAY\")\n        icon:SetTexture(modTable.TEX_SKULL)\n        icon:SetSize(cfg.iconSkullSize or 26, cfg.iconSkullSize or 26)\n        if icon.SetDrawLayer then\n            icon:SetDrawLayer(\"OVERLAY\", 7)\n        end\n        \n        local side = tonumber(cfg.iconAnchorSide) or 7\n        local map  = envTable.anchorMap[side] or {\"BOTTOMLEFT\", \"BOTTOMLEFT\"}\n        \n        icon:ClearAllPoints()\n        icon:SetPoint(map[1], unitFrame, map[2], 0, 0)\n        icon:Hide()\n        \n        envTable.questIcon = icon\n    else\n        local icon = envTable.questIcon\n        if icon.SetParent then icon:SetParent(container) end\n        if icon.SetDrawLayer then icon:SetDrawLayer(\"OVERLAY\", 7) end\n    end\n    \n    if not envTable.questText then\n        local text = Plater:CreateLabel(container)\n        text:SetJustifyH(\"CENTER\")\n        text:SetJustifyV(\"MIDDLE\")\n        text:SetText(\"\")\n        text:Hide()\n        \n        if text.SetDrawLayer then\n            text:SetDrawLayer(\"OVERLAY\", 7)\n        end\n        \n        -- Default-Font merken (wichtig für sauberes Fallback)\n        local f, s, fl = text:GetFont()\n        text.__ameDefaultFont  = f\n        text.__ameDefaultSize  = s\n        text.__ameDefaultFlags = fl\n        \n        envTable.questText = text\n    else\n        local text = envTable.questText\n        if text.SetParent then text:SetParent(container) end\n        if text.SetDrawLayer then text:SetDrawLayer(\"OVERLAY\", 7) end\n        \n        if not text.__ameDefaultFont then\n            local f, s, fl = text:GetFont()\n            text.__ameDefaultFont  = f\n            text.__ameDefaultSize  = s\n            text.__ameDefaultFlags = fl\n        end\n    end\n    \n    if not envTable.groupBadge then\n        local badge = container:CreateTexture(nil, \"OVERLAY\")\n        badge:SetSize(cfg.groupBadgeSize or 18, cfg.groupBadgeSize or 18)\n        \n        if badge.SetDrawLayer then\n            badge:SetDrawLayer(\"OVERLAY\", 7)\n        end\n        \n        if badge.SetAtlas and modTable.ATLAS_GROUP then\n            badge:SetAtlas(modTable.ATLAS_GROUP)\n        end\n        \n        badge:Hide()\n        envTable.groupBadge = badge\n    else\n        local badge = envTable.groupBadge\n        if badge.SetParent then badge:SetParent(container) end\n        if badge.SetDrawLayer then badge:SetDrawLayer(\"OVERLAY\", 7) end\n    end\n    \nend",
},
