["Hooks"] = {
["Nameplate Added"] = "------------------------------------------------------------\n-- NAMEPLATE ADDED\n------------------------------------------------------------\nfunction (self, unitId, unitFrame, envTable, modTable)\n    envTable.unitIsCaster = false\n    \n    local plate = C_NamePlate.GetNamePlateForUnit(unitId)\n    if not plate then return end\n    \n    modTable.AME_Update(plate, unitId, unitFrame, envTable)\n    \nend",
["Deinitialization"] = "------------------------------------------------------------\n-- DEINITIALIZATION\n------------------------------------------------------------\nfunction (modTable)\n    \n    for _, plate in pairs(C_NamePlate.GetNamePlates()) do\n        local c = plate.AME_IND\n        \n        if c then\n            -- Pool leeren, falls vorhanden\n            if modTable._wipeContainer then\n                modTable._wipeContainer(c)\n            end\n            \n            -- Container ausblenden\n            c:Hide()\n        end\n    end\n    \nend",
["Nameplate Updated"] = "------------------------------------------------------------\n-- NAMEPLATE ADDED / UPDATED\n------------------------------------------------------------\nfunction (self, unitId, unitFrame, envTable, modTable)\n    \n    local plate = C_NamePlate.GetNamePlateForUnit(unitId)\n    if not plate then return end\n    \n    if modTable.AME_Update then\n        modTable.AME_Update(plate, unitId, unitFrame, envTable)\n    end\n    \nend",
["Initialization"] = "------------------------------------------------------------\n-- INITIALIZATION\n------------------------------------------------------------\nfunction (modTable)\n    \n    local WB_SCALE = 1.25\n    \n    ------------------------------------------------------------\n    -- CONTAINER\n    ------------------------------------------------------------\n    local function ensureContainer(plateFrame, unitFrame)\n        if plateFrame.AME_IND then\n            return plateFrame.AME_IND\n        end\n        \n        local f = CreateFrame(\"Frame\", nil, unitFrame)\n        f:SetSize(1, 1)\n        f:SetFrameStrata(\"HIGH\")\n        f:SetFrameLevel((unitFrame:GetFrameLevel() or 1) + 15)\n        f.pool = {}\n        f.count = 0\n        \n        plateFrame.AME_IND = f\n        return f\n    end\n    \n    ------------------------------------------------------------\n    -- STRATA\n    ------------------------------------------------------------\n    local function refreshZ(container, unitFrame, hb)\n        if not container or not unitFrame then return end\n        \n        container:SetParent(UIParent)\n        container:SetFrameStrata(\"DIALOG\")\n        \n        local base = unitFrame:GetFrameLevel() or 1\n        if hb and hb.GetFrameLevel then\n            base = math.max(base, hb:GetFrameLevel() or 1)\n        end\n        container:SetFrameLevel(base + 120)\n    end\n    \n    local function resetZ(container, unitFrame)\n        if not container or not unitFrame then return end\n        container:SetParent(unitFrame)\n        container:SetFrameStrata(unitFrame:GetFrameStrata() or \"MEDIUM\")\n        container:SetFrameLevel((unitFrame:GetFrameLevel() or 1) + 15)\n    end\n    \n    local function layout(container, hb, anchor, xOff, yOff, baseSize)\n        if not hb then return end\n        \n        container:ClearAllPoints()\n        container:SetSize(baseSize, baseSize)\n        \n        anchor = (anchor or \"LEFT\"):upper()\n        container:SetPoint(anchor, hb, anchor, xOff or 0, yOff or 0)\n        container:Show()\n    end\n    \n    ------------------------------------------------------------\n    -- TEXTURE POOL\n    ------------------------------------------------------------\n    local function wipeContainer(container)\n        if not container then return end\n        \n        for i = 1, #container.pool do\n            local t = container.pool[i]\n            t:Hide()\n            t:ClearAllPoints()\n        end\n        \n        container.count = 0\n    end\n    \n    local function getNextTex(container)\n        container.count = container.count + 1\n        local idx = container.count\n        \n        if not container.pool[idx] then\n            local t = container:CreateTexture(nil, \"OVERLAY\")\n            t:SetDrawLayer(\"OVERLAY\", 7)\n            container.pool[idx] = t\n        end\n        \n        local tex = container.pool[idx]\n        tex:Show()\n        return tex, idx\n    end\n    \n    ------------------------------------------------------------\n    -- ICON DRAW\n    ------------------------------------------------------------\n    local function addOne(container, kind, size, spacing, growSide)\n        local tex, idx = getNextTex(container)\n        \n        tex:SetVertexColor(1, 1, 1)\n        tex:SetDesaturated(false)\n        tex:SetTexCoord(0, 1, 0, 1)\n        tex:SetBlendMode(\"BLEND\")\n        tex:ClearAllPoints()\n        \n        if kind == \"elite\" then\n            tex:SetAtlas(\"nameplates-icon-elite-gold\", true)\n            tex:SetSize(size, size)\n            \n        elseif kind == \"rare\" then\n            tex:SetAtlas(\"nameplates-icon-elite-silver\", true)\n            tex:SetSize(size, size)\n            \n        elseif kind == \"wb\" then\n            tex:SetAtlas(\"DungeonSkull\", true)\n            tex:SetSize(size * WB_SCALE, size * WB_SCALE)\n            \n        elseif kind == \"caster\" then\n            tex:SetTexture(\"Interface\\\\AddOns\\\\MerfinPlus\\\\Media\\\\textures\\\\merfinplus_staff.blp\")\n            tex:SetSize(size, size)\n            \n        elseif kind == \"quest\" then\n            tex:SetTexture(\"INV_Staff_2H_DraenorRaid_D_01\")\n            tex:SetSize(size, size)\n            \n        elseif kind == \"pet\" then\n            tex:SetTexture(\"Interface\\\\AddOns\\\\Plater\\\\images\\\\peticon\")\n            tex:SetSize(size, size)\n        end\n        \n        if idx == 1 then\n            tex:SetPoint(\"CENTER\", container, \"CENTER\", 0, 0)\n        else\n            local prev = container.pool[idx - 1]\n            if growSide == \"RIGHT\" then\n                tex:SetPoint(\"LEFT\", prev, \"RIGHT\", spacing, 0)\n            else\n                tex:SetPoint(\"RIGHT\", prev, \"LEFT\", -spacing, 0)\n            end\n        end\n    end\n    \n    local function addIcons(container, icons, size, spacing, growSide)\n        for i = 1, #icons do\n            addOne(container, icons[i], size, spacing, growSide)\n        end\n    end\n    \n    ------------------------------------------------------------\n    -- MAIN UPDATE\n    ------------------------------------------------------------\n    function modTable.AME_Update(plateFrame, unitId, unitFrame, envTable)\n        if not unitFrame or not unitFrame.healthBar then return end\n        \n        -- Hide Plater default indicators\n        if plateFrame.IconIndicators then\n            plateFrame.IconIndicators.Next = 1\n            for _, tex in ipairs(plateFrame.IconIndicators) do\n                tex:Hide()\n                tex:SetAlpha(0)\n                tex:SetTexture(nil)\n            end\n        end\n        \n        -- Kill extra overlays\n        local function kill(tex)\n            if not tex then return end\n            tex:SetAlpha(0)\n            tex:Hide()\n            tex.Show = function() end\n            tex.SetShown = function() end\n            tex.SetAlpha = function() end\n            tex.SetTexture = function() end\n            tex.SetAtlas = function() end\n        end\n        \n        -- WICHTIG:\n        -- targetOverlay / targetOverlayTexture NICHT killen,\n        -- sonst verschwindet Platers Ziel-Overlay-Textur.\n        kill(unitFrame.softInteractIcon)\n        kill(unitFrame.FocusIndicator)\n        \n        if unitFrame.IndicatorFrame then\n            local f = unitFrame.IndicatorFrame\n            f.canShowElite = false\n            f.canShowRare  = false\n            f.canShowQuest = false\n            f.canShowBoss  = false\n            \n            kill(f.EliteIcon)\n            kill(f.RareIcon)\n            kill(f.QuestIcon)\n            kill(f.WorldBossIcon)\n        end\n        \n        --------------------------------------------------------\n        -- AME ICON SYSTEM\n        --------------------------------------------------------\n        local t  = unitFrame.actorType or unitFrame.ActorType or plateFrame.actorType\n        local c  = ensureContainer(plateFrame, unitFrame)\n        local hb = unitFrame.healthBar\n        \n        local anchor  = (modTable.config.INDanchor or \"LEFT\"):upper()\n        local size    = tonumber(modTable.config.INDsize) or 14\n        local spacing = tonumber(modTable.config.INDspacing) or 2\n        local xOff    = tonumber(modTable.config.INDx) or -4\n        local yOff    = tonumber(modTable.config.INDy) or 0\n        \n        -- INDgrowth: ON = right, OFF = left\n        local grow = modTable.config.INDgrowth and \"RIGHT\" or \"LEFT\"\n        \n        if modTable.config.INDstrata then\n            refreshZ(c, unitFrame, hb)\n        else\n            resetZ(c, unitFrame)\n        end\n        \n        layout(c, hb, anchor, xOff, yOff, size)\n        wipeContainer(c)\n        \n        -- Friendly NPC: no icons\n        if t == \"friendlynpc\" then return end\n        if t ~= \"enemynpc\" and t ~= \"friendlynpc\" then return end\n        \n        --------------------------------------------------------\n        -- Decide which icons to show\n        --------------------------------------------------------\n        local wantQuest, wantRare, wantElite, wantSkull, wantPet, wantCaster = false, false, false, false, false, false\n        \n        -- Quest\n        local isQuestObj = plateFrame.namePlateIsQuestObjective and true or false\n        wantQuest =\n        (modTable.config.INDtest and modTable.config.INDquest) or\n        (not modTable.config.INDtest and (\n                (t ~= \"friendlynpc\" and modTable.config.INDquest and isQuestObj) or\n                (t == \"friendlynpc\" and modTable.config.INDfnquest and isQuestObj)\n        ))\n        \n        -- =========================================\n        -- CLEAN CLASSIFICATION (LIKE COLOR MOD)\n        -- =========================================\n        \n        local cls = UnitClassification(unitId)\n        \n        local inInstance, instanceType = IsInInstance()\n        local isDungeon = inInstance and (instanceType == \"party\" or instanceType == \"raid\")\n        \n        local playerLevel = UnitLevel(\"player\")\n        local level = UnitEffectiveLevel(unitId)\n        \n        -- Boss\n        local isBoss = level == playerLevel + 2 or level == -1\n        \n        -- Lieutenant\n        local isLieutenant =\n        level == playerLevel + 1\n        or unitFrame.namePlateIsBossMob\n        or (UnitIsLieutenant and UnitIsLieutenant(unitId))\n        \n        -- Caster\n        local isCaster = false\n        if envTable and envTable.unitIsCaster then -- cached\n            isCaster = true\n        else\n            local classBase = UnitClassBase(unitId)\n            local isPaladin = not issecretvalue(classBase) and classBase == \"PALADIN\"\n            local powerType = UnitPowerType(unitId)\n            isCaster = isPaladin or powerType == Enum.PowerType.Mana\n        end\n        \n        -- Worldboss\n        local isWB = (cls == \"worldboss\")\n        \n        -- Icon logic\n        if modTable.config.INDtest then\n            \n            if modTable.config.INDrare  then wantRare  = true end\n            if modTable.config.INDelite then wantElite = true end\n            if modTable.config.INDshowwb then wantSkull = true end\n            \n        else\n            \n            if isDungeon then\n                -- 🏰 DUNGEON MODE\n                \n                if isBoss then\n                    wantSkull = true\n                    \n                elseif isLieutenant then\n                    wantElite = true\n                    \n                elseif isCaster then\n                    wantCaster = true\n                end\n                \n            else\n                -- 🌍 OPEN WORLD\n                \n                if isBoss then\n                    wantSkull = true\n                    \n                elseif isWB and modTable.config.INDshowwb then\n                    wantElite = true\n                    wantSkull = true\n                    \n                elseif isLieutenant then\n                    wantElite = true\n                    \n                elseif cls == \"rare\" and modTable.config.INDrare then\n                    wantRare = true\n                    \n                elseif (cls == \"elite\" or cls == \"rareelite\") and modTable.config.INDelite then\n                    wantElite = true\n                end\n            end\n        end\n        -- Pet\n        local unitType = Plater and Plater.GetUnitType and Plater.GetUnitType(plateFrame)\n        if modTable.config.INDpet and (modTable.config.INDtest or unitType == \"pet\") then\n            wantPet = true\n        end\n        \n        --------------------------------------------------------\n        -- Fixed priority (always same order):\n        -- Pet > Skull > Elite > Rare > Quest\n        --------------------------------------------------------\n        local icons = {}\n        if wantPet    then table.insert(icons, \"pet\")    end\n        if wantSkull  then table.insert(icons, \"wb\")     end\n        if wantElite  then table.insert(icons, \"elite\")  end\n        if wantCaster then table.insert(icons, \"caster\") end\n        if wantRare   then table.insert(icons, \"rare\")   end\n        if wantQuest  then table.insert(icons, \"quest\")  end\n        \n        addIcons(c, icons, size, spacing, grow)\n    end\n    \n    ------------------------------------------------------------\n    -- MANUAL REFRESH (force update all visible nameplates)\n    ------------------------------------------------------------\n    function modTable.AME_UpdateAll()\n        for _, plate in pairs(C_NamePlate.GetNamePlates()) do\n            local uf = plate.unitFrame\n            if uf and uf.namePlateUnitToken then\n                modTable.AME_Update(plate, uf.namePlateUnitToken, uf, {})\n            end\n        end\n    end\n    \n    modTable._wipeContainer = wipeContainer\nend",
["Nameplate Removed"] = "------------------------------------------------------------\n-- NAMEPLATE REMOVED\n------------------------------------------------------------\nfunction (self, unitId, unitFrame, envTable, modTable)\n    \n    local plate = C_NamePlate.GetNamePlateForUnit(unitId)\n    if not plate or not plate.AME_IND then return end\n    \n    local c = plate.AME_IND\n    if modTable._wipeContainer then\n        modTable._wipeContainer(c)\n    end\n    \nend",
},
